	 * @return bool
	 */
	function SendPong() {
		return CkWebSocket_SendPong($this->_cPtr);
	}

	/**
	 * Creates an asynchronous task to call the SendPong method with the arguments provided.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkWebSocketRef.html#SendPongAsync
	 * @return ?CkTask
	 */
	function SendPongAsync() {
		return chilkat::_obj(CkWebSocket_SendPongAsync($this->_cPtr),'CkTask');
	}

	/**
	 * Causes the calling WebSocket object to share the already-established WebSocket connection owned by ws.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkWebSocketRef.html#ShareConnection
	 * @param CkWebSocket $ws
	 * @return bool
	 */
	function ShareConnection($ws) {
		return CkWebSocket_ShareConnection($this->_cPtr,$ws);
	}

	/**
	 * Associates this WebSocket object with an existing, connected Rest object and prepares it for a client-side WebSocket session.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkWebSocketRef.html#UseConnection
	 * @param CkRest $connection
	 * @return bool
	 */
	function UseConnection($connection) {
		return CkWebSocket_UseConnection($this->_cPtr,$connection);
	}

	/**
	 * Validates the server's response to the WebSocket opening handshake sent through the associated Rest object.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkWebSocketRef.html#ValidateServerHandshake
	 * @return bool
	 */
	function ValidateServerHandshake() {
		return CkWebSocket_ValidateServerHandshake($this->_cPtr);
	}
}
